P='https://www.pmi.it/?p=362269'; V='https://telematici.agenziaentrate.gov.it/VerificaCF/IVerificaCfPf.jsp'; AR='https://arcom.agenziaentrate.gov.it/CitizenArCom/'
def a(u,t,it=True): return f'<a href="{u}" rel="noopener noreferrer"'+(' lang="it"' if it else '')+f'>{t}</a>'
def table(h,rows):
    th=''.join(f'<th>{x}</th>' for x in h); tr=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)
    return f'<div class="table-wrap"><table>\n<thead><tr>{th}</tr></thead>\n<tbody>\n{tr}\n</tbody></table></div>'
def ctable(h,pairs):
    rows=[[pairs[i][0],f'<code>{pairs[i][1]}</code>',pairs[i+1][0],f'<code>{pairs[i+1][1]}</code>'] for i in range(0,len(pairs),2)]
    return table(h,rows)
